package vtable

// isSpecs are the columns of PostgreSQL 16's information_schema views,
// in PostgreSQL's order, read from a PostgreSQL 16 server. A column is
// a sql_identifier (text) unless its name carries a suffix: :c
// character_data (text), :y yes_or_no (varchar(3)), :i cardinal_number
// (integer), :t time_stamp (timestamptz(2)).
